<template><div class="card"><div class="flex items-center justify-between gap-3 mb-5"><div><div class="font-semibold text-xl">{{L.title}}</div><div class="text-muted-color mt-1">{{L.subtitle}}</div></div><Button :label="L.refresh" icon="pi pi-refresh" severity="secondary" outlined :loading="loading" @click="load"/></div><DataTable :value="cards" :loading="loading" stripedRows class="p-datatable-sm"><Column field="created_at" :header="L.created"><template #body="{data}">{{fmt(data.created_at)}}</template></Column><Column :header="L.status"><template #body="{data}"><Tag :value="statusLabel(data.status)" :severity="data.status==='approved'?'success':'danger'"/></template></Column><Column field="reviewed_at" :header="L.reviewed"><template #body="{data}">{{fmt(data.reviewed_at)}}</template></Column><Column :header="L.type"><template #body="{data}">{{typeLabel(data.card_type)}}</template></Column><Column field="target_name" :header="L.target"/><Column field="creator_name" :header="L.creator"/><Column field="reviewer_name" :header="L.reviewer"/><Column field="reason" :header="L.reason"/></DataTable></div></template><script setup>import{onMounted,ref}from'vue';import api from'@/service/api';import { useAuthStore } from '@/stores/auth';import Button from'primevue/button';import DataTable from'primevue/datatable';import Column from'primevue/column';import Tag from'primevue/tag';const L={title:'\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u0430\u0440\u0442\u043e\u0447\u0435\u043a',subtitle:'\u041e\u0434\u043e\u0431\u0440\u0435\u043d\u043d\u044b\u0435 \u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0435 \u0437\u0430\u044f\u0432\u043a\u0438',refresh:'\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c',created:'\u0421\u043e\u0437\u0434\u0430\u043d\u0430',status:'\u0421\u0442\u0430\u0442\u0443\u0441',reviewed:'\u0420\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0430',type:'\u0422\u0438\u043f',target:'\u0426\u0435\u043b\u044c',creator:'\u0421\u043e\u0437\u0434\u0430\u043b',reviewer:'\u0420\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043b',reason:'\u041f\u0440\u0438\u0447\u0438\u043d\u0430'};const labels={admin_warn:'\u041f\u0440\u0435\u0434',admin_unwarn:'\u0421\u043d\u044f\u0442\u0438\u0435 \u043f\u0440\u0435\u0434\u0430',admin_promote:'\u041f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u0435',admin_demote:'\u041f\u043e\u043d\u0438\u0436\u0435\u043d\u0438\u0435',admin_rename:'\u0421\u043c\u0435\u043d\u0430 \u043d\u0438\u043a\u0430',admin_donate:'\u0414\u043e\u043d\u0430\u0442',player_permanent_ban:'\u0412\u0435\u0447\u043d\u0438\u043a'};const authStore=useAuthStore();const cards=ref([]),loading=ref(false);function typeLabel(t){return labels[t]||t}function statusLabel(s){return s==='approved'?'\u041e\u0434\u043e\u0431\u0440\u0435\u043d\u0430':'\u041e\u0442\u043a\u0430\u0437'}function fmt(v){return v?new Date(v).toLocaleString('ru-RU'):'—'}async function load(){loading.value=true;try{const serverParam=authStore.currentServer ? `?server=${authStore.currentServer}` : '';const{data}=await api.get(`/admin/cards/history${serverParam}`);cards.value=data.cards||[]}finally{loading.value=false}}onMounted(load)</script>
